CREATE TABLE problems (problem_id text PRIMARY KEY, content_version bigint NOT NULL CHECK(content_version>=0), public_prompt text NOT NULL, answer_format jsonb NOT NULL, validator_spec jsonb NOT NULL, registered_hints jsonb NOT NULL, fixture_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE activity_runs (id uuid PRIMARY KEY, character_id uuid NOT NULL REFERENCES characters(id), problem_id text NOT NULL REFERENCES problems(problem_id), started_session_id uuid NOT NULL, last_session_id uuid NOT NULL, status text NOT NULL CHECK(status IN ('ready','solving','awaiting_hint','solved','ended')), version bigint NOT NULL CHECK(version>=0), hints_used int NOT NULL CHECK(hints_used BETWEEN 0 AND 1), auto_attempts_used int NOT NULL CHECK(auto_attempts_used>=0), auto_attempts_granted int NOT NULL CHECK(auto_attempts_granted>=3), last_step_no bigint NOT NULL CHECK(last_step_no>=0), started_at timestamptz NOT NULL, ended_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(character_id,id), FOREIGN KEY(character_id,started_session_id) REFERENCES sessions(character_id,id), FOREIGN KEY(character_id,last_session_id) REFERENCES sessions(character_id,id), CHECK(auto_attempts_used<=auto_attempts_granted), CHECK((status IN ('solved','ended'))=(ended_at IS NOT NULL)));
CREATE UNIQUE INDEX activity_runs_one_open_uq ON activity_runs(character_id) WHERE status IN ('ready','solving','awaiting_hint');
CREATE TABLE activity_steps (id uuid PRIMARY KEY, character_id uuid NOT NULL, activity_run_id uuid NOT NULL, step_no bigint NOT NULL CHECK(step_no>=0), event_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('answer_submitted','answer_judged','hint_used','retry_granted','ended')), identity_id uuid REFERENCES identities(id), normalized_answer text, hint_id text, verdict text CHECK(verdict IN ('correct','incorrect')), data_status text NOT NULL CHECK(data_status IN ('active','invalidated')), applied_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(character_id,id), UNIQUE(character_id,event_id), UNIQUE(activity_run_id,step_no), FOREIGN KEY(character_id,activity_run_id) REFERENCES activity_runs(character_id,id), FOREIGN KEY(character_id,event_id) REFERENCES events(character_id,id), CHECK(data_status='invalidated' OR (kind='answer_submitted' AND normalized_answer IS NOT NULL AND hint_id IS NULL AND verdict IS NULL) OR (kind='answer_judged' AND verdict IS NOT NULL AND normalized_answer IS NULL AND hint_id IS NULL) OR (kind='hint_used' AND hint_id IS NOT NULL AND normalized_answer IS NULL AND verdict IS NULL) OR (kind IN ('retry_granted','ended') AND normalized_answer IS NULL AND hint_id IS NULL AND verdict IS NULL)));
CREATE UNIQUE INDEX activity_steps_answer_uq ON activity_steps(activity_run_id,normalized_answer) WHERE kind='answer_submitted' AND data_status='active';
CREATE UNIQUE INDEX activity_steps_hint_uq ON activity_steps(activity_run_id,hint_id) WHERE kind='hint_used' AND data_status='active';
CREATE TABLE relationships (character_id uuid NOT NULL REFERENCES characters(id), identity_id uuid NOT NULL REFERENCES identities(id), familiarity double precision NOT NULL CHECK(familiarity>=0 AND familiarity<=1), affinity double precision NOT NULL CHECK(affinity>=0 AND affinity<=1), interaction_days int NOT NULL CHECK(interaction_days>=0), verified_problem_count int NOT NULL CHECK(verified_problem_count>=0), verified_help_days int NOT NULL CHECK(verified_help_days>=0), last_help_at timestamptz, projection_version bigint NOT NULL CHECK(projection_version>=0), updated_at timestamptz NOT NULL, PRIMARY KEY(character_id,identity_id));
CREATE TABLE relationship_evidence (id uuid PRIMARY KEY, character_id uuid NOT NULL, identity_id uuid NOT NULL REFERENCES identities(id), evidence_key text NOT NULL, kind text NOT NULL CHECK(kind IN ('first_observed','praise','direct_insult','verified_hint')), status text NOT NULL CHECK(status IN ('active','invalidated')), problem_id text REFERENCES problems(problem_id), effective_at timestamptz NOT NULL, local_date date NOT NULL, order_version bigint NOT NULL CHECK(order_version>=0), config_version bigint NOT NULL, features jsonb, applied jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(character_id,id), UNIQUE(character_id,identity_id,evidence_key), FOREIGN KEY(character_id,config_version) REFERENCES character_configs(character_id,version), CHECK((kind='verified_hint')=(problem_id IS NOT NULL)));
CREATE INDEX evidence_rebuild_idx ON relationship_evidence(character_id,identity_id,effective_at,order_version,id);
CREATE TABLE relationship_evidence_sources (evidence_id uuid NOT NULL, event_id uuid NOT NULL, character_id uuid NOT NULL, event_revision bigint NOT NULL CHECK(event_revision>=0), role text NOT NULL, support_group text NOT NULL, PRIMARY KEY(evidence_id,event_id), FOREIGN KEY(character_id,evidence_id) REFERENCES relationship_evidence(character_id,id), FOREIGN KEY(character_id,event_id) REFERENCES events(character_id,id));
CREATE INDEX evidence_sources_event_idx ON relationship_evidence_sources(character_id,event_id,evidence_id);
CREATE TABLE memories (id uuid PRIMARY KEY, character_id uuid NOT NULL, session_id uuid NOT NULL, activity_run_id uuid, memory_key text NOT NULL, kind text NOT NULL CHECK(kind IN ('activity_result','verified_help','unfinished_activity','delivered_proposal')), status text NOT NULL CHECK(status IN ('active','superseded','invalidated','deleted')), content_version bigint NOT NULL CHECK(content_version>=0), fact_kind text NOT NULL CHECK(fact_kind='observed'), visibility text NOT NULL CHECK(visibility='test_public'), content text, facts jsonb, occurred_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, superseded_by_memory_id uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(character_id,id), UNIQUE(character_id,memory_key), FOREIGN KEY(character_id,session_id) REFERENCES sessions(character_id,id), FOREIGN KEY(character_id,activity_run_id) REFERENCES activity_runs(character_id,id), FOREIGN KEY(character_id,superseded_by_memory_id) REFERENCES memories(character_id,id), CHECK((status='deleted' AND content IS NULL AND facts IS NULL) OR (status<>'deleted' AND content IS NOT NULL AND facts IS NOT NULL)));
ALTER TABLE response_sources ADD FOREIGN KEY(character_id,memory_id) REFERENCES memories(character_id,id);
CREATE INDEX memories_active_recent_idx ON memories(character_id,occurred_at DESC,id DESC) WHERE status='active';
CREATE TABLE memory_sources (memory_id uuid NOT NULL, event_id uuid NOT NULL, character_id uuid NOT NULL, event_revision bigint NOT NULL CHECK(event_revision>=0), role text NOT NULL, PRIMARY KEY(memory_id,event_id), FOREIGN KEY(character_id,memory_id) REFERENCES memories(character_id,id), FOREIGN KEY(character_id,event_id) REFERENCES events(character_id,id));
CREATE INDEX memory_sources_event_idx ON memory_sources(character_id,event_id,memory_id);
CREATE TABLE memory_participants (memory_id uuid NOT NULL, identity_id uuid NOT NULL REFERENCES identities(id), character_id uuid NOT NULL, role text NOT NULL, PRIMARY KEY(memory_id,identity_id), FOREIGN KEY(character_id,memory_id) REFERENCES memories(character_id,id));
CREATE INDEX memory_participants_identity_idx ON memory_participants(character_id,identity_id,memory_id);
CREATE TABLE agendas (id uuid PRIMARY KEY, character_id uuid NOT NULL, source_memory_id uuid NOT NULL, source_memory_version bigint NOT NULL CHECK(source_memory_version>=0), activity_run_id uuid NOT NULL, created_session_id uuid NOT NULL, status text NOT NULL CHECK(status IN ('pending','reserved','offered','accepted','declined','expired')), not_before timestamptz NOT NULL, expires_at timestamptz NOT NULL, offered_at timestamptz, last_attempt_session_id uuid, closed_reason text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(character_id,id), UNIQUE(character_id,activity_run_id), UNIQUE(character_id,source_memory_id), FOREIGN KEY(character_id,source_memory_id) REFERENCES memories(character_id,id), FOREIGN KEY(character_id,activity_run_id) REFERENCES activity_runs(character_id,id), FOREIGN KEY(character_id,created_session_id) REFERENCES sessions(character_id,id), FOREIGN KEY(character_id,last_attempt_session_id) REFERENCES sessions(character_id,id), CHECK(status<>'offered' OR offered_at IS NOT NULL), CHECK(expires_at>not_before));
CREATE TABLE agenda_attempts (id uuid PRIMARY KEY, character_id uuid NOT NULL, agenda_id uuid NOT NULL, session_id uuid NOT NULL, response_id uuid NOT NULL UNIQUE, reserved_at timestamptz NOT NULL, delivery_status text NOT NULL CHECK(delivery_status IN ('reserved','not_delivered','delivered_text','delivered_audio','unknown')), resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(character_id,id), UNIQUE(character_id,session_id), FOREIGN KEY(character_id,agenda_id) REFERENCES agendas(character_id,id), FOREIGN KEY(character_id,session_id,response_id) REFERENCES response_runs(character_id,session_id,id));
CREATE TABLE tasks (id uuid PRIMARY KEY, character_id uuid NOT NULL, session_id uuid NOT NULL, kind text NOT NULL CHECK(kind='consolidate_session'), dedupe_key text NOT NULL, status text NOT NULL CHECK(status IN ('pending','running','result_ready','completed','failed','cancelled')), payload jsonb NOT NULL, result jsonb, available_at timestamptz NOT NULL, lease_until timestamptz, lease_token uuid, attempts int NOT NULL CHECK(attempts>=0), max_attempts int NOT NULL CHECK(max_attempts BETWEEN 1 AND 3 AND attempts<=max_attempts), last_error text, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(character_id,id), UNIQUE(character_id,kind,dedupe_key), FOREIGN KEY(character_id,session_id) REFERENCES sessions(character_id,id), CHECK((status='running' AND lease_until IS NOT NULL AND lease_token IS NOT NULL) OR (status<>'running' AND lease_until IS NULL AND lease_token IS NULL)));
CREATE INDEX tasks_due_idx ON tasks(available_at,id) WHERE status='pending';
CREATE INDEX tasks_expired_lease_idx ON tasks(lease_until,id) WHERE status='running';
